const body = $json.body ?? $json;
const required = ['version','correlation_id','source','actor','target','action','timestamp'];
const missing = required.filter(k => body[k] === undefined || body[k] === null || body[k] === '');
if (missing.length) { return [{json:{ok:false,status:'blocked',reason:'missing_fields',missing,correlation_id:body.correlation_id ?? null,timestamp:new Date().toISOString()}}]; }
return [{json:{...body,_validated:true}}];

const item = $json;
if (item.ok === false) return [{json:item}];
const registry = {
  'repo.inspect':'R0',
  'repo.read_file':'R0',
  'repo.list_prs':'R0',
  'repo.list_issues':'R0',
  'repo.compare_refs':'R0',
  'repo.health_summary':'R0',
  'repo.create_branch':'R1',
  'repo.create_draft_file':'R1',
  'repo.open_draft_pr':'R1',
  'repo.create_issue':'R1',
  'repo.update_tracked_file':'R2',
  'repo.modify_workflow':'R2',
  'repo.modify_integration_config':'R2',
  'repo.merge_pr':'R3',
  'repo.delete_file':'R3',
  'repo.delete_branch':'R3',
  'repo.change_permissions':'R3',
  'repo.change_visibility':'R3',
  'secrets.write':'R3',
  'production.deploy':'R3'
};
const risk = registry[item.action];
if (!risk) return [{json:{ok:false,status:'blocked',reason:'unknown_action',correlation_id:item.correlation_id,timestamp:new Date().toISOString()}}];
if (risk === 'R3') return [{json:{ok:false,status:'blocked',reason:'prohibited_action',risk_class:risk,correlation_id:item.correlation_id,timestamp:new Date().toISOString()}}];
if (risk === 'R1' || risk === 'R2') return [{json:{ok:false,status:'blocked',reason:'approval_required',risk_class:risk,correlation_id:item.correlation_id,timestamp:new Date().toISOString()}}];
return [{json:{...item,risk_class:risk,decision:'allowed'}}];

const x = $json;
if (x.ok === false) return [{json:x}];
return [{json:{ok:true,correlation_id:x.correlation_id,status:'accepted',action:x.action,risk_class:x.risk_class,approval:'not_required',result:{message:'R0 request accepted by bridge skeleton. Handler not yet connected.'},timestamp:new Date().toISOString()}}];
